export interface QueryProcedure<O> {
  readonly kind: 'query';
  readonly output: O;
}
export interface MutationProcedure<O> {
  readonly kind: 'mutation';
  readonly output: O;
}
export interface StreamProcedure<O> {
  readonly kind: 'stream';
  readonly output: O;
}
export type AnyProcedure = QueryProcedure<unknown> | MutationProcedure<unknown> | StreamProcedure<unknown>;
export interface RouterRecord {
  [key: string]: AnyProcedure | RouterRecord | Router<RouterRecord>;
}
export interface Router<R extends RouterRecord = RouterRecord> {
  readonly record: R;
  readonly isRouter: true;
}
export interface ProcedureBuilder {
  input<S>(schema: S): ProcedureBuilder;
  query<O>(resolver: (options: { input: unknown }) => O): QueryProcedure<O>;
  mutation<O>(resolver: (options: { input: unknown }) => O): MutationProcedure<O>;
  stream<O>(resolver: (options: { input: unknown }) => O): StreamProcedure<O>;
}
export interface Kit {
  procedure: ProcedureBuilder;
  router<R extends RouterRecord>(record: R): Router<R>;
}
export interface Init {
  create(): Kit;
}
export declare const init: Init;
export interface Reply {
  status: number;
}
export declare function serveRpc<R extends Router>(options: { router: R; endpoint: string; request: unknown }): Promise<Reply>;

// The client side: a proxy whose members are the router's keys.
type Inner<R> = R extends Router<infer S> ? S : R;
export type ClientOf<R> = {
  [K in keyof R]: R[K] extends QueryProcedure<infer O>
    ? { query(input?: unknown): Promise<O> }
    : R[K] extends MutationProcedure<infer O>
      ? { mutate(input?: unknown): Promise<O> }
      : ClientOf<Inner<R[K]>>;
};
export declare function createClient<R extends Router>(options: { url: string }): ClientOf<R["record"]>;

export type HooksOf<R> = {
  [K in keyof R]: R[K] extends QueryProcedure<infer O>
    ? { useQuery(input?: unknown): { data: O | undefined } }
    : R[K] extends MutationProcedure<unknown>
      ? { useMutation(): { mutate(input?: unknown): void } }
      : HooksOf<Inner<R[K]>>;
};
export declare function createHooks<R extends Router>(): HooksOf<R["record"]>;

export type OptionsOf<R> = {
  [K in keyof R]: R[K] extends QueryProcedure<unknown>
    ? { queryOptions(input?: unknown): { key: string[] } }
    : R[K] extends MutationProcedure<unknown>
      ? { mutationOptions(): { key: string[] } }
      : OptionsOf<Inner<R[K]>>;
};
export interface ContextKit<R extends Router> {
  useProxy(): OptionsOf<R["record"]>;
}
export declare function createContext<R extends Router>(): ContextKit<R>;
